Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';. (Join-Path $PSScriptRoot 'Common-Light.ps1');$paths=Get-LightPaths;Assert-LightModel $paths
if(Test-NetConnection 127.0.0.1 -Port 18080 -InformationLevel Quiet -WarningAction SilentlyContinue){throw 'Port 18080 is already in use.'}
$env:LLAMA_API_KEY=Read-LightCredential;try{$arguments=@('--model',$paths.Model,'--host','127.0.0.1','--port','18080','--ctx-size','2048','--parallel','1','--threads','4','--gpu-layers','0','--no-webui','--log-disable');$process=Start-Process -FilePath $paths.Server -ArgumentList $arguments -WindowStyle Hidden -PassThru}catch{throw}finally{Remove-Item Env:LLAMA_API_KEY -ErrorAction SilentlyContinue}
Start-Sleep -Milliseconds 500;if($process.HasExited){throw 'Light server exited during startup.'};$state=[ordered]@{schemaVersion=1;pid=$process.Id;startedUtc=$process.StartTime.ToUniversalTime().ToString('o');executablePath=$paths.Server;modelSha256='7485fe6f11af29433bc51cab58009521f205840f5b4ae3a32fa7f92e8534fdf5';host='127.0.0.1';port=18080;context=2048;parallel=1;threads=4;gpuLayers=0};[IO.File]::WriteAllText($paths.StateFile,($state|ConvertTo-Json),[Text.UTF8Encoding]::new($false));Write-Output "Light server started: PID=$($process.Id)"
